// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 wei);
        vm.prank(address(0x1));
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "fallback failed");

        address target = address(0x2);
        vm.deal(target, 0);
        c.sendMoney(target, 0);

        assertTrue(c.depositsCount() == 1, "depositsCount should be 1");
    }
}
